<script setup>
import {ref,computed,watch} from 'vue';
import {api,ask,notify,changed,can,state} from '../lib/workspace';
import Icon from './Icon.vue';
const props=defineProps({companyId:{type:Number,required:true}});
const emit=defineEmits(['dirty','busy']);
const payload=ref(null),settings=ref({}),busy=ref(false),error=ref(''),templateId=ref('unrestricted'),templateName=ref(''),templateDescription=ref('');
const canEdit=computed(()=>state.session?.user?.role==='admin'&&can('system.companies','edit'));
const baseline=ref('');let sequence=0;
const dirty=computed(()=>!!payload.value&&JSON.stringify(settings.value)!==baseline.value);
const restrictions=computed(()=>(payload.value?.fields||[]).filter(f=>f.type==='boolean'));
const enabledCount=computed(()=>restrictions.value.filter(f=>settings.value[f.key]).length);
watch(dirty,value=>emit('dirty',value));watch(busy,value=>emit('busy',value));
function accept(data){if(state.companyId===props.companyId&&state.session)state.session.operational_settings={...data.settings};payload.value=data;settings.value={...data.settings};baseline.value=JSON.stringify(settings.value);}
async function load(){const seq=++sequence,cid=props.companyId;busy.value=true;error.value='';payload.value=null;try{const data=await api(`/companies/${cid}/operational-settings`);if(seq===sequence)accept(data);}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}}
watch(()=>props.companyId,load,{immediate:true});
async function save(){if(busy.value||!canEdit.value||!payload.value)return;const invalid=payload.value.fields.find(f=>f.type==='integer'&&(!Number.isInteger(settings.value[f.key])||settings.value[f.key]<(f.min||1)||(f.max&&settings.value[f.key]>f.max)));if(invalid){error.value=`Confira o valor de ${invalid.label}.`;return;}busy.value=true;error.value='';try{accept(await api(`/companies/${props.companyId}/operational-settings`,{method:'PUT',body:{settings:{...settings.value},version:payload.value.version}}));changed();notify('Parâmetros operacionais salvos para esta empresa.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function reloadSaved(){if(busy.value)return;if(dirty.value&&!await ask({title:'Recarregar parâmetros salvos?',message:'As alterações locais serão descartadas e a versão mais recente será carregada.',confirmLabel:'Recarregar'}))return;await load();}
function restoreDefaults(){if(busy.value||!canEdit.value||!payload.value)return;settings.value={...payload.value.defaults};}
async function applyTemplate(){if(busy.value||!canEdit.value||!payload.value)return;busy.value=true;error.value='';try{if(dirty.value&&!await ask({title:'Substituir alterações não salvas?',message:'Aplicar o modelo substitui e salva os parâmetros operacionais desta empresa.',confirmLabel:'Aplicar modelo'}))return;accept(await api(`/companies/${props.companyId}/operational-settings/apply-template`,{method:'POST',body:{template_id:templateId.value,version:payload.value.version}}));changed();notify('Modelo aplicado à empresa.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function saveTemplate(){if(busy.value||!canEdit.value||dirty.value||!templateName.value.trim())return;busy.value=true;error.value='';try{accept(await api(`/companies/${props.companyId}/operational-settings/templates`,{method:'POST',body:{name:templateName.value.trim(),description:templateDescription.value.trim()}}));templateName.value='';templateDescription.value='';notify('Modelo salvo para reutilizar em outras empresas.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="operational-settings" :aria-busy="busy">
<h3>Parâmetros operacionais da empresa</h3><p>Importação, exclusão e limpeza sem restrições operacionais por padrão. Ative apenas as regras que esta empresa precisa.</p>
<div v-if="error" class="message error" role="alert">{{error}}<button type="button" class="text-button" :disabled="busy" @click="reloadSaved">{{payload?'Recarregar versão salva':'Tentar novamente'}}</button></div>
<p v-if="busy" role="status"><Icon name="loading" :size="16"/> Atualizando parâmetros…</p>
<p v-if="payload&&!canEdit" class="message info">Somente administradores com permissão de edição de empresas podem alterar estes parâmetros.</p><template v-if="payload"><div class="summary-strip"><strong>{{enabledCount?`${enabledCount} restrição(ões) ativa(s)`:'Sem restrições operacionais'}}</strong><span>{{dirty?'Alterações ainda não salvas':'Configuração salva'}}</span></div>
<div class="operational-rules"><label v-for="field in restrictions" :key="field.key" class="choice-card"><input type="checkbox" v-model="settings[field.key]" :disabled="busy||!canEdit"/><div><strong>{{field.label}}</strong><small>{{field.description}}</small></div></label></div>
<div class="form-grid operational-limits"><template v-for="field in payload.fields.filter(f=>f.type==='integer')" :key="field.key"><label v-if="field.key==='import_size_mb'?settings.limit_import_size:settings.limit_batch_selection">{{field.label}}<input type="number" v-model.number="settings[field.key]" :min="field.min||1" :max="field.max" step="1" :disabled="busy||!canEdit"/><small>{{field.description}}</small></label></template></div>
<div class="actions operational-actions"><button type="button" class="button outline" :disabled="busy||!canEdit" @click="restoreDefaults">Restaurar padrão sem restrições</button><button type="button" class="button primary" :disabled="busy||!canEdit||!dirty" @click="save">Salvar parâmetros</button></div>
<details class="operational-models"><summary>Modelos reutilizáveis</summary><p>Aplique um modelo salvo ou crie um modelo com os parâmetros salvos desta empresa.</p><label>Modelo<select v-model="templateId" :disabled="busy||!canEdit"><option v-for="model in payload.templates" :key="model.id" :value="model.id">{{model.name}}</option></select></label><p class="field-help">{{payload.templates.find(t=>t.id===templateId)?.description}}</p><button type="button" class="button outline" :disabled="busy||!canEdit" @click="applyTemplate">Aplicar e salvar modelo na empresa</button><div class="form-grid"><label>Nome do novo modelo<input v-model="templateName" maxlength="100" :disabled="busy||!canEdit" placeholder="Ex.: Rotina do escritório"/></label><label>Descrição (opcional)<input v-model="templateDescription" maxlength="500" :disabled="busy||!canEdit"/></label></div><p v-if="dirty" class="field-help">Salve os parâmetros antes de criar o modelo.</p><button type="button" class="button outline" :disabled="busy||!canEdit||dirty||!templateName.trim()" @click="saveTemplate">Salvar configuração como modelo</button></details>
<div class="message subtle"><Icon name="shield"/><span>Permissões, integridade dos vínculos e segurança de arquivos continuam obrigatórias. Ações irreversíveis mantêm o resumo do efeito e um botão final explícito, sem exigir confirmação duplicada. Limites técnicos de processamento não são regras operacionais.</span></div></template>
</section></template>
<style scoped>
.operational-settings>p{color:var(--muted);line-height:1.6}.operational-rules{display:grid;grid-template-columns:1fr 1fr;gap:10px}.operational-rules .choice-card{margin:0;align-items:flex-start}.operational-rules small{display:block;margin-top:5px;line-height:1.5}.operational-limits,.operational-actions{margin-top:18px}.operational-actions{flex-wrap:wrap;justify-content:space-between}.operational-models{margin:22px 0;border-top:1px solid var(--line);padding-top:16px}.operational-models summary{cursor:pointer;font-weight:600}.operational-models .form-grid{margin:18px 0}.operational-models>label{margin-top:12px}.operational-settings .summary-strip{margin:16px 0;justify-content:space-between}@media(max-width:760px){.operational-rules{grid-template-columns:1fr}}
</style>
